WITH valid AS (SELECT *, ROUND(discount_pct * 0.85, 2) AS adjusted_discount_pct, ROUND(discount_pct, 1) AS discount_pct_rounded, COALESCE(channel, 'DIRECT') AS channel_clean FROM promotions WHERE ends_on > '2024-07-01') SELECT CASE WHEN discount_pct >= 0.28 THEN 'HIGH' ELSE 'LOW' END AS discount_pct_tier, COUNT(*) FILTER (WHERE channel = 'web') AS web_rows, SUM(CASE WHEN channel = 'partner' THEN discount_pct_rounded ELSE 0 END) AS partner_discount_pct_rounded, COUNT(DISTINCT id) AS distinct_ids, MIN(adjusted_discount_pct) AS min_adjusted_discount_pct FROM valid GROUP BY CASE WHEN discount_pct >= 0.28 THEN 'HIGH' ELSE 'LOW' END ORDER BY partner_discount_pct_rounded DESC NULLS FIRST
